function bugunMetni2() { const d = BUGUN; return d.toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', weekday: 'long' }); }

function kaynakBul(m) { const t = m.toLocaleLowerCase('tr'); if (/tl|taksit|ücret|indirim|fiyat/.test(t)) return 'Fiyat ve taksit'; if (/rapor|belge|fotoğraf|evrak/.test(t)) return 'Evraklar'; if (/saat|cumartesi|ders/.test(t)) return 'Ders saatleri'; if (/hafta|ay|süre/.test(t)) return 'Süre'; return 'Kurs bilgileri'; }

/* ---------- Deneme başarısı (UYG-005, KAY-069): öğrenci uygulamasındaki deneme sınavları kurs panelinde ---------- */
// Deneme sınavı 50 soru, 70 puan geçer. "Sınava hazır": en az 3 deneme ve son 3'ünün hepsi 70 ve üstü.
const dnSuz = { ara: '', suz: 'hepsi' };
function denemeOzet() {
  return sb(S.kursiyerler).filter(k => !k.kapali && k.asama !== 'Ehliyet' && !egitimSinifi(k.sinif) && !(k.esinav && k.esinav.sonuc === 'Geçti') && !k.muaf).map(k => {
    const p = (k.deneme || []).map(x => typeof x === 'object' && x ? +x.puan || 0 : +x || 0), n = p.length, g = p.filter(x => x >= 70).length, son3 = p.slice(-3);
    return { k, n, gecen: g, kalan: n - g, oran: n ? Math.round(g / n * 100) : 0, son: n ? p[n - 1] : null, ort: n ? Math.round(p.reduce((a, x) => a + x, 0) / n) : null, hazir: n >= 3 && son3.every(x => x >= 70), yarim: (k.denemeDetay || []).filter(x => x.tur === 'deneme' && !x.tamam).length };
  });
}
function denemeTablo() {
  const q = dnSuz.ara.trim().toLocaleLowerCase('tr'), l = denemeOzet().filter(x => (!q || tamAd(x.k).toLocaleLowerCase('tr').includes(q)) && (dnSuz.suz === 'hepsi' || (dnSuz.suz === 'alti' && x.n && x.oran < 70) || (dnSuz.suz === 'hazirdegil' && !x.hazir) || (dnSuz.suz === 'hazir' && x.hazir) || (dnSuz.suz === 'yok' && !x.n)))
    .sort((a, b) => (b.n ? 1 : 0) - (a.n ? 1 : 0) || a.oran - b.oran || tamAd(a.k).localeCompare(tamAd(b.k), 'tr'));
  if (!l.length) return `<div class="kart-govde"><p style="color:var(--soluk);font-size:14px">Bu süzgeçte öğrenci yok.</p></div>`;
  return `<div class="tablo-kap"><table class="tablo"><thead><tr><th>Öğrenci</th><th>Sınıf</th><th class="sayi">Deneme</th><th class="sayi">Geçti</th><th class="sayi">Kaldı</th><th class="sayi">Başarı</th><th class="sayi">Son puan</th><th>Sınava hazır</th></tr></thead><tbody>${l.map(x => `<tr><td><a href="#/kursiyer/${e(x.k.id)}">${e(tamAd(x.k))}</a>${x.yarim ? ` <small style="color:var(--soluk)">· ${x.yarim} yarım</small>` : ''}</td><td>${e(sinifEtiket(x.k.sinif, x.k))}</td><td class="sayi">${x.n}</td><td class="sayi">${x.gecen}</td><td class="sayi">${x.kalan}</td><td class="sayi" style="color:${x.n && x.oran < 70 ? 'var(--kirmizi)' : 'var(--murekkep)'}">${x.n ? '%' + x.oran : '—'}</td><td class="sayi">${x.son ?? '—'}</td><td>${x.hazir ? rozet('Hazır', 'basari') : x.n < 3 ? rozet(x.n ? 'Az deneme' : 'Deneme yok', 'notr') : rozet('Hazır değil', 'uyari')}</td></tr>`).join('')}</tbody></table></div>`;
}
function denemeHtml() {
  const o = denemeOzet(), dn = o.filter(x => x.n);
  return `<div class="kart"><div class="kart-bas"><h3>Deneme sınavı başarısı</h3><small>${dn.length} öğrenci deneme çözdü · ${o.filter(x => x.hazir).length} öğrenci sınava hazır (son 3 deneme 70 ve üstü) · e-Sınavı geçen ve muaf öğrenciler listede yok</small></div>
    <div class="kart-govde" style="display:flex;gap:10px;flex-wrap:wrap;align-items:center"><input class="girdi" data-dn-ara placeholder="Öğrenci ara" value="${e(dnSuz.ara)}" style="max-width:240px" aria-label="Öğrenci ara">
    <select class="girdi" data-dn-suz style="max-width:240px" aria-label="Süzgeç">${[['hepsi', 'Hepsi'], ['alti', 'Başarısı %70’in altında'], ['hazirdegil', 'Sınava hazır olmayanlar'], ['hazir', 'Sınava hazır'], ['yok', 'Hiç deneme çözmeyenler']].map(([v, t]) => `<option value="${v}"${dnSuz.suz === v ? ' selected' : ''}>${t}</option>`).join('')}</select></div>
    <div data-dn-tablo>${denemeTablo()}</div></div>`;
}
